contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint am, uint minSum) public payable {
        require(address(this).balance >= amount);
        c.SetMinSum(minSum);
        c.Deposit{value: amount}();
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;
        c.Collect(am);
        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;
        bool cond = (balBefore >= minSum && balBefore >= am);
        assert(
            (cond
                ? (balBefore - balAfter == am && contractBalBefore - contractBalAfter == am)
                : (balAfter == balBefore && contractBalAfter == contractBalBefore))
        );
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint d1, uint d2, uint am) public payable {
        require(d1 > 0);
        require(d2 > 0);
        require(am <= d1 + d2);
        c.SetMinSum(0);
        c.Deposit{value: d1}();
        c.Deposit{value: d2}();
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        assert(
            !reverted &&
            address(c).balance == d1 + d2 - am &&
            c.balances(address(this)) == d1 + d2 - am &&
            address(this).balance >= am
        );
    }
    receive() external payable {}
}

