contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        // initialize contract so deposits work
        c.SetLogFile(address(this));
        c.Initialized();

        // build up a balance via deposit
        c.Deposit{value: depositAmount}();

        // set MinSum strictly above the deposited balance
        c.SetMinSum(depositAmount + 1);

        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;

        // attempt to collect (any amount, even <= balance)
        c.Collect(collectAmount);

        uint balAfter = c.balances(address(this));
        uint ethAfter = address(c).balance;

        assert(balAfter == balBefore && ethAfter == ethBefore);
    }

    receive() external payable {}
}

